INSERT INTO experiences (lang, slug, title, subtitle, headline, description, `includes`, price, priceLabel, duration, ctaText, seoText, imageUrl, galleryImages, isActive, sortOrder) VALUES ('en', 'forest-picnic', 'Forest Picnic', 'Outdoor indulgence – straight from our kitchen into nature', 'Your Picnic Among Trees and Birdsong', 'Some moments simply taste better outdoors. Our forest picnic is made for exactly these moments: a lovingly packed picnic basket, a bottle of chilled sparkling wine and a quiet spot among the trees of the Wiehengebirge hills.

You choose whether we fill your basket with a hearty breakfast or a cold lunch – both freshly prepared in our kitchen. Add a bottle of sparkling wine for two, tableware and a blanket. All you need is a free morning and a desire for fresh air.

The picnic can be booked as an add-on to any overnight stay at Waldhotel Bad Essen. Whether as a surprise, a shared start to the day or a relaxed lunch in the countryside – this experience makes your stay truly special.', '["Picnic basket for 2 persons","Breakfast or cold lunch of your choice","1 bottle of sparkling wine (chilled)","Tableware, cutlery and picnic blanket","Recommendations for the most beautiful spots nearby"]', 'from 54.00 €', 'per picnic for 2 persons · bookable with any overnight stay', 'Bookable with any overnight stay', 'Enquire about picnic', 'A forest picnic is one of the most beautiful experiences Bad Essen has to offer. Waldhotel Bad Essen is located directly at the Wiehengebirge hills and provides the ideal starting point for a picnic in nature. Whether as a romantic experience for two, as an addition to a short break or as a special moment during a hike – our picnic basket with sparkling wine makes every stay unforgettable. Enjoy fresh air, regional delicacies and the silence of the forest.', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663365901872/gP4ek7BMjABi6Nex8zFehy/picknick-wald-1-devMVvDTFps7AW2comDxSd.webp', '["https://d2xsxph8kpxj0f.cloudfront.net/310519663365901872/gP4ek7BMjABi6Nex8zFehy/picknick-wald-1-devMVvDTFps7AW2comDxSd.webp","https://d2xsxph8kpxj0f.cloudfront.net/310519663365901872/gP4ek7BMjABi6Nex8zFehy/picknick-wald-2-ioXg2dD3hycw6ocTD9fMsG.webp","https://d2xsxph8kpxj0f.cloudfront.net/310519663365901872/gP4ek7BMjABi6Nex8zFehy/picknick-wald-3-WrDXX5j77Jq57w76dvtDp2.webp","https://d2xsxph8kpxj0f.cloudfront.net/310519663365901872/gP4ek7BMjABi6Nex8zFehy/picknick-wald-4-e267ug7xPua2azZP4hjV5j.webp"]', true, 1);

